import 'package:flutter/material.dart';
import 'package:nutmeg/api/CloudFunctionsUtils.dart';
import 'package:nutmeg/l10n/app_localizations.dart';
import 'package:nutmeg/utils/CrashlyticsLogger.dart';
import 'package:nutmeg/utils/UiUtils.dart';
import 'package:nutmeg/widgets/Containers.dart';
import 'package:nutmeg/widgets/Skeletons.dart';

final _logger = CrashlyticsLogger("MatchPreview");

/// News-style preview of the lineup, generated by the backend.
/// Renders nothing when there is no preview or it fails to load.
class MatchPreview extends StatefulWidget {
  final String matchId;

  const MatchPreview({Key? key, required this.matchId}) : super(key: key);

  @override
  State<MatchPreview> createState() => _MatchPreviewState();
}

class _MatchPreviewState extends State<MatchPreview> {
  Map<String, dynamic>? _preview;
  bool _loading = true;
  bool _requested = false;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_requested) return;
    _requested = true;
    _load(Localizations.localeOf(context).languageCode);
  }

  Future<void> _load(String lang) async {
    try {
      var data = await CloudFunctionsClient().get(
          "matches/${widget.matchId}/preview",
          args: {"lang": lang});
      if (mounted) setState(() => _preview = data);
    } catch (e) {
      _logger.warning("Could not load match preview: $e");
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return InfoContainer(
        child: Column(children: [
          Skeletons.fullWidthText,
          SizedBox(height: 8),
          Skeletons.fullWidthText,
          SizedBox(height: 8),
          Skeletons.fullWidthText,
        ]),
      );
    }
    var preview = _preview;
    if (preview == null) return SizedBox.shrink();

    var l10n = AppLocalizations.of(context)!;
    return InfoContainerWithTitle(
      title: l10n.matchPreviewTitle,
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(preview["headline"] ?? "", style: TextPalette.h2),
          SizedBox(height: 8),
          Text(preview["body"] ?? "", style: TextPalette.bodyText),
        ],
      ),
    );
  }
}
